/*
 * prog50_binary_heap.c
 *
 * Original behaviour (observed from the obfuscated binary):
 *
 *   - If the program is started without any command‑line arguments
 *     (i.e. argc < 2) it prints the single line "NOOP" and exits.
 *
 *   - Otherwise it treats each argument (argv[1] … argv[argc‑1]) as a
 *     command for a fixed‑size (capacity 16) min‑heap of signed 64‑bit
 *     integers.
 *
 *   - Supported commands
 *
 *       I<number>   Insert the signed decimal integer <number> into the
 *                   heap.  On success prints   "INS %ld\n"   with the
 *                   inserted value.  If the heap already contains 16
 *                   elements prints "FULL".  If the argument does not
 *                   contain a valid integer prints "ERR".
 *
 *       X           Extract the minimum element from the heap.  On success
 *                   prints   "MIN %ld\n"   with the extracted value.
 *                   If the heap is empty prints "EMPTY".
 *
 *   - Any other argument (including a malformed “I” command) results in
 *     printing the line "ERR".
 *
 *   - The program never reads from stdin and never writes anything else
 *     to stdout.
 *
 * The implementation below reproduces exactly that observable behaviour.
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>

#define HEAP_CAPACITY 16

/* Global state – matches the original binary's .bss symbols */
static long heap[HEAP_CAPACITY];
static int  size = 0;

/* swap two elements of the heap */
static void heap_swap(int i, int j)
{
    long tmp = heap[i];
    heap[i] = heap[j];
    heap[j] = tmp;
}

/* percolate the element at index `idx` up until the min‑heap property holds */
static void heap_percolate_up(int idx)
{
    while (idx > 0) {
        int parent = (idx - 1) / 2;
        if (heap[parent] <= heap[idx])
            break;
        heap_swap(parent, idx);
        idx = parent;
    }
}

/* percolate the element at index `idx` down until the min‑heap property holds */
static void heap_percolate_down(int idx)
{
    while (1) {
        int left  = idx * 2 + 1;
        int right = left + 1;

        if (left >= size)               /* no children */
            break;

        int smallest = left;
        if (right < size && heap[right] < heap[left])
            smallest = right;

        if (heap[idx] <= heap[smallest])
            break;

        heap_swap(idx, smallest);
        idx = smallest;
    }
}

/* insert a value into the heap; returns 0 on success, 1 if full */
static int heap_insert(long value)
{
    if (size >= HEAP_CAPACITY)
        return 1;               /* FULL */

    heap[size] = value;
    heap_percolate_up(size);
    ++size;
    return 0;
}

/* extract the minimum value; caller must ensure the heap is non‑empty */
static long heap_extract_min(void)
{
    long min = heap[0];
    heap[0] = heap[size - 1];
    --size;
    heap_percolate_down(0);
    return min;
}

/* ---------------------------------------------------------------------- */
int main(int argc, char **argv)
{
    if (argc < 2) {
        puts("NOOP");
        return 0;
    }

    for (int i = 1; i < argc; ++i) {
        const char *cmd = argv[i];

        if (cmd[0] == 'I') {                     /* INSERT */
            char *endptr;
            long val = strtol(cmd + 1, &endptr, 10);

            /* malformed number? */
            if (endptr == cmd + 1 || *endptr != '\0') {
                puts("ERR");
                continue;
            }

            if (heap_insert(val) != 0) {         /* heap full */
                puts("FULL");
                continue;
            }

            printf("INS %ld\n", val);
        }
        else if (cmd[0] == 'X' && cmd[1] == '\0') {   /* EXTRACT MIN */
            if (size == 0) {
                puts("EMPTY");
                continue;
            }

            long min = heap_extract_min();
            printf("MIN %ld\n", min);
        }
        else {                                   /* unknown command */
            puts("ERR");
        }
    }

    return 0;
}
